css:
html[data-theme-id] {
  --studio-composer-border: #d5d5d5;
  --studio-composer-icon: #252525;
  --studio-main-control-hover: #e4e4e4;
  --studio-main-control-pressed: #d4d4d4;
  --studio-composer-focus: #949494;
  --studio-composer-focused-border: #bcbcbc;
  --studio-composer-shadow: 0 3px 15px rgb(0 0 0 / 9%);
  --studio-ui-font: "Segoe UI Variable Text", "Segoe UI", "Microsoft YaHei UI", "PingFang SC", "Noto Sans CJK SC", system-ui, sans-serif;
}

html.dark[data-theme-id] {
  --studio-composer-border: #4b4b4b;
  --studio-composer-icon: #e7e7e7;
  --studio-main-control-hover: #414141;
  --studio-main-control-pressed: #505050;
  --studio-composer-focus: #818181;
  --studio-composer-focused-border: #626262;
  --studio-composer-shadow: 0 3px 15px rgb(0 0 0 / 34%);
}

[data-chat-composer-overlay].bottom-0 {
  padding-block-start: 0;
}

[data-chat-composer-overlay].bottom-0 [data-chat-composer-stack] > .relative > [aria-hidden="true"]:last-child {
  height: calc(env(safe-area-inset-bottom, 0px) + 0.5rem);
}

html[data-theme-id] :is([data-slot="sidebar-inner"], [data-slot="sidebar"][data-mobile], [data-slot="sidebar-inset"]) {
  --surface-grain: none;
}

html[data-theme-id] :is([data-slot="sidebar-inner"], [data-slot="sidebar"][data-mobile]) {
  font-family: var(--studio-ui-font);
}

html[data-theme-id] [data-slot="sidebar-inner"] {
  border-inline-end: 1px solid var(--app-theme-sidebar-border);
}

[data-sidebar-row^="folder:"],
[data-thread-item] > [data-sidebar-row] {
  border-radius: 0.5rem;
}

[data-sidebar-row^="folder:"] > .truncate {
  font-size: 0.8125rem;
  font-weight: 600;
}

[data-thread-item] > [data-sidebar-row] .truncate.text-start {
  font-size: 0.875rem;
}

[data-thread-item] > [data-sidebar-row][aria-current="page"] .truncate.text-start {
  font-weight: 400;
}

@media (hover: hover) and (pointer: fine) {
  [data-sidebar-row]:is([aria-current="page"], .bg-sidebar-row-selected):hover,
  [data-slot="sidebar-menu-button"][data-active="true"]:hover {
    background-color: color-mix(in srgb, var(--app-theme-sidebar-row-active) 65%, var(--studio-main-control-pressed));
  }

  [data-testid="sidebar-project-folder"]:not(:first-child) {
    margin-block-start: 0.25rem;
  }

  [data-chat-composer-surface][data-chat-composer-mobile-collapsed="false"] > [data-chat-composer-body] {
    padding-block-start: 0.75rem;
    padding-block-end: 0.25rem;
    padding-inline: 1.0625rem;
  }

  [data-chat-composer-surface][data-chat-composer-mobile-collapsed="false"] .composer-tiptap {
    min-height: calc(1.6lh + 0.5rem);
  }

  [data-chat-composer-surface][data-chat-composer-mobile-collapsed="false"] > [data-chat-composer-footer] {
    padding-inline: 0.75rem;
  }
}

@media (hover: hover) and (pointer: fine) and (prefers-reduced-motion: no-preference) {
  [data-sidebar-row] {
    transition: background-color 135ms ease-out, opacity 135ms ease-out;
  }

  [data-slot="sidebar-menu-button"] {
    transition-property: width, height, padding, background-color;
    transition-duration: 135ms;
    transition-timing-function: ease-out;
  }
}

html[data-theme-id] [data-chat-header] {
  box-shadow: inset 0 -1px var(--app-theme-toolbar-border);
  font-family: var(--studio-ui-font);
}

html[data-theme-id] [data-slot="composer-shell"] {
  --chat-composer-outline: var(--studio-composer-border);
  --ring: var(--studio-composer-focus);
  --studio-composer-radius: 1.0625rem;
  font-family: var(--studio-ui-font);
}

html[data-theme-id] [data-slot="composer-shell"]:focus-within {
  --chat-composer-outline: var(--studio-composer-focused-border);
}

[data-slot="composer-shell"]::before,
[data-slot="composer-host"]::before,
[data-chat-composer-main-surface] {
  border-radius: var(--studio-composer-radius);
  backdrop-filter: none;
}

[data-slot="composer-host"] {
  border-radius: var(--studio-composer-radius);
  box-shadow: none;
}

[data-chat-composer-main-surface] {
  box-shadow: inset 0 0 0 1px var(--chat-composer-outline), var(--studio-composer-shadow);
}

[data-slot="composer-host"]::after,
[data-chat-composer-main-surface]::after {
  box-shadow: none;
}

[data-chat-composer-footer] button[type="submit"],
button[data-chat-composer-transition-actions] {
  border-radius: 0.625rem;
}

[data-chat-composer-form] .composer-tiptap,
[data-chat-composer-body] > .relative > .flow-root > .text-placeholder {
  font-family: inherit;
  font-size: inherit;
  line-height: 1.5;
}

[data-message-role="assistant"] .chat-markdown,
[data-user-message-body] {
  font-family: var(--studio-ui-font);
  font-size: 0.9375rem;
  line-height: 1.5;
}

[data-message-role="assistant"] .chat-markdown :is(pre, code) {
  font-family: var(--font-mono);
}

@media (hover: hover) and (pointer: fine) {
  @container composer-surface (min-width: 34rem) {
    :where([data-chat-composer-stack] > .relative:has(> .relative > [data-slot="composer-shell"])) {
      & [data-slot="composer-host"]::after {
        border: 0;
      }

      & [data-chat-composer-form] > .relative:last-child {
        padding-block-end: 2.125rem;
      }

      & [data-chat-composer-surface][data-chat-composer-mobile-collapsed="false"] {
        --studio-prompt-basis: max-content;
        --studio-prompt-offset: 0px;
        --studio-prompt-top: 0.5rem;
        position: relative;
        display: flex;
        flex-wrap: wrap;
        align-items: center;
        min-block-size: 2.875rem;
      }

      & [data-chat-composer-surface]:has(> [data-chat-composer-footer] > div:first-child:not([data-chat-composer-actions])) {
        --studio-prompt-offset: 2rem;
      }

      & [data-chat-composer-surface]:has(
        > [data-chat-composer-body] > .mb-3,
        > [data-chat-composer-body] > .relative > .flow-root > div > .composer-tiptap > :not(p:only-child),
        > [data-chat-composer-body] > .relative > .flow-root > div > .composer-tiptap > p br:not(.ProseMirror-trailingBreak)
      ) {
        --studio-prompt-basis: 100%;
        --studio-prompt-offset: 0px;
        --studio-prompt-top: 0.75rem;
      }

      & [data-chat-composer-surface][data-chat-composer-mobile-collapsed="false"]::before {
        content: "";
        flex: 0 0 var(--studio-prompt-offset);
        block-size: 0;
      }

      & [data-chat-composer-surface] > :not([data-chat-composer-body], [data-chat-composer-footer]) {
        flex: 0 0 100%;
      }

      & [data-chat-composer-surface][data-chat-composer-mobile-collapsed="false"] > [data-chat-composer-body] {
        flex: 1 1 var(--studio-prompt-basis);
        min-inline-size: 0;
        max-inline-size: 100%;
        padding-block: var(--studio-prompt-top) 0.5rem;
        padding-inline: 1rem 0.625rem;
      }

      & [data-chat-composer-surface][data-chat-composer-mobile-collapsed="false"] .composer-tiptap {
        min-height: calc(1lh + 0.5rem);
      }

      & [data-chat-composer-footer] {
        flex: 0 0 auto;
        margin-inline-start: auto;
        min-block-size: 2.5rem;
        max-inline-size: 100%;
        padding: 0 0.5rem;
      }

      & [data-chat-composer-footer] > :not([data-chat-composer-actions]) {
        position: absolute;
        inset-inline-start: 0.5rem;
        display: flex;
        align-self: center;
        margin: 0;
      }

      & [data-chat-composer-actions="right"] {
        flex: 0 0 auto;
      }

      & [data-chat-composer-footer-controls] {
        position: absolute;
        inset-block-start: calc(100% + 0.125rem);
        inset-inline-end: 0.75rem;
        width: max-content;
        max-width: calc(100% - 1.5rem);
      }

      & [data-chat-composer-footer-controls] [data-chat-provider-model-picker] {
        block-size: 1.75rem;
        padding-inline: 0.5rem;
        font-size: 0.8125rem;
      }
    }
  }
}

[data-chat-composer-footer] button[aria-label="Attach files"] > svg > path {
  d: path("M12 4.5V19.5M4.5 12H19.5");
  stroke-width: 2;
}

[data-chat-composer-actions="right"] button[aria-label="Submit message"] > svg > path {
  d: path("M12.25 3.5V6.5A2.25 2.25 0 0 1 10 8.75H2.25M5.5 5.5L2.25 8.75L5.5 12");
  stroke-width: 1.15;
}

button[data-chat-composer-transition-actions][aria-label="Send message"] > svg > path {
  d: path("M14 4V7.25A2.5 2.5 0 0 1 11.5 9.75H2.75M6.25 6.25L2.75 9.75L6.25 13.25");
  stroke-width: 1.35;
}

@media (min-width: 48rem) and (hover: hover) and (pointer: fine) {
  [data-chat-composer-overlay].bottom-0 > .chat-composer-lane {
    padding-inline-start: calc(env(safe-area-inset-left, 0px) + 2rem + var(--chat-lane-inset-start, 0px));
    padding-inline-end: calc(env(safe-area-inset-right, 0px) + 2rem + var(--chat-lane-inset-end, 0px));
  }

  [data-chat-composer-overlay].bottom-0 [data-chat-composer-stack] {
    max-width: calc(var(--chat-content-max-width) + 2rem);
  }

  [data-chat-composer-overlay].bottom-0 :is([data-slot="composer-shell"], [data-chat-composer-form]) {
    max-width: none;
  }
}

@media (prefers-reduced-motion: no-preference) {
  [data-chat-composer-main-surface] {
    transition: box-shadow 150ms ease-out;
  }
}

[data-chat-composer-surface] :is(
  button[aria-label="Attach files"],
  button[aria-label="Start voice input"],
  button[type="submit"].bg-message-action[aria-label],
  button[data-chat-composer-transition-actions],
  button[aria-label="Resume thread"],
  button[aria-label="Stop generation"],
  button[aria-label="Stopping"],
  [data-chat-provider-model-picker]:not(:where([data-chat-composer-footer-controls] *))
) {
  --control-icon-color: currentColor;
  color: var(--studio-composer-icon);
  background-color: transparent;
  border-radius: 0.5625rem;
  box-shadow: none;
  scale: none;
  transition: none;

  &:is(:hover, :focus-visible):not(:disabled, [aria-disabled="true"], [data-disabled]) {
    background-color: var(--studio-main-control-hover);
  }

  &:is(:active, [data-pressed], [data-popup-open], [aria-expanded="true"]):not(:disabled, [aria-disabled="true"], [data-disabled]) {
    background-color: var(--studio-main-control-pressed);
  }

  &:focus-visible {
    outline: 2px solid var(--studio-composer-focus);
    outline-offset: -2px;
  }

  &:is(:disabled, [aria-disabled="true"], [data-disabled]) {
    opacity: 0.5;
  }

  @media (prefers-reduced-motion: no-preference) {
    transition: background-color 110ms ease-out;
  }
}

[data-chat-composer-surface] :is(
  button[aria-label="Attach files"],
  button[aria-label="Start voice input"],
  button[type="submit"].bg-message-action[aria-label],
  button[data-chat-composer-transition-actions],
  button[aria-label="Resume thread"],
  button[aria-label="Stop generation"],
  button[aria-label="Stopping"]
) {
  display: inline-flex;
  flex: none;
  align-items: center;
  justify-content: center;
  inline-size: 2rem;
  block-size: 2rem;
  min-inline-size: 0;
  min-block-size: 0;
  border: 0;
  padding: 0;
  will-change: auto;

  @media (hover: hover) and (pointer: fine) {
    inline-size: 1.875rem;
    block-size: 1.875rem;
  }

  & > svg {
    color: inherit;
    inline-size: 1.125rem;
    block-size: 1.125rem;
    margin: 0;
    translate: none;
  }
}

[data-chat-composer-surface] [data-chat-composer-footer-controls] button[data-chat-provider-model-picker] {
  --studio-model-picker-tint: 0%;
  --control-icon-color: currentColor;
  color: var(--studio-composer-icon);
  background-color: transparent;
  border-radius: 0.4375rem;
  box-shadow: none;
  scale: none;
  transition: none;
  font-family: var(--studio-ui-font);
  font-weight: 500;

  &::before {
    content: "";
    order: 1;
    flex: none;
    inline-size: 0.3125rem;
    block-size: 0.3125rem;
    margin-inline: 0.125rem 0.0625rem;
    border-right: 1px solid currentColor;
    border-bottom: 1px solid currentColor;
    color: var(--app-theme-text-muted, var(--muted-foreground));
    transform: translateY(-1px) rotate(45deg);
    pointer-events: none;
  }

  &:is(:hover, :focus-visible, :active, [data-pressed], [data-popup-open], [aria-expanded="true"]):not(:disabled, [aria-disabled="true"], [data-disabled]) {
    background-color: color-mix(
      in srgb,
      color-mix(in srgb, var(--studio-composer-icon) var(--studio-model-picker-tint), transparent) var(--glass-opacity, 100%),
      transparent
    );
  }

  @media (hover: hover) {
    &:hover {
      --studio-model-picker-tint: 9%;
    }
  }

  &:is(:active, [data-pressed], [data-popup-open], [aria-expanded="true"]) {
    --studio-model-picker-tint: 14%;
  }

  &:focus-visible {
    outline: 2px solid var(--studio-composer-focus);
    outline-offset: -2px;
  }

  &:is(:disabled, [aria-disabled="true"], [data-disabled]) {
    opacity: 0.5;
  }

  @media (prefers-reduced-motion: no-preference) {
    transition: background-color 140ms ease-out;
  }

  & :is([data-chat-provider-model-picker-icon], [data-chat-provider-model-picker-label] + span:has(> [data-composer-control-label], > svg)) {
    color: var(--app-theme-text-muted, var(--muted-foreground));
  }

  & [data-chat-provider-model-picker-label] + span:has(> [data-composer-control-label], > svg) {
    gap: 0.25rem;
    font-size: 0.875em;
  }
}

[data-chat-composer-form] .composer-tiptap p {
  word-break: break-all;
}

[data-chat-composer-form] .composer-tiptap p :is(code, [contenteditable="false"]) {
  word-break: normal;
}

html[data-theme-id] button[class~="[:hover,[data-pressed]]:bg-accent"]:not(:where([data-chat-composer-surface] *)) {
  @media (prefers-reduced-motion: no-preference) {
    transition-property: background-color, box-shadow, scale;
    transition-duration: 110ms;
  }
}

html[data-theme-id] :is(
  :is(button[class~="[:hover,[data-pressed]]:bg-accent"], button[class~="[:hover,[data-pressed]]:bg-accent/50"]):not(:where([data-chat-composer-surface] *)),
  [data-chat-header] :is([data-slot="button"], [data-slot="menu-trigger"], [data-toolbar-control]),
  [data-slot="select-trigger"]:not(:where([data-chat-composer-surface] *)),
  :is([data-sidebar-row], [data-slot="sidebar-menu-button"]),
  [data-slot="menu-item"],
  [data-slot="menu-checkbox-item"],
  [data-slot="menu-radio-item"],
  [data-slot="menu-sub-trigger"],
  [data-slot="select-item"],
  [data-slot="autocomplete-item"],
  [data-slot="combobox-item"],
  [data-slot="command-item"]
):not(:disabled, [aria-disabled="true"], [data-disabled]):is(:active, [data-pressed], [data-popup-open], [aria-haspopup][aria-expanded="true"]) {
  background-color: var(--studio-main-control-pressed);

  &.surface-glass {
    background-color: color-mix(in srgb, var(--studio-main-control-pressed) var(--glass-opacity), transparent);
  }
}

html[data-theme-id] [data-slot="command-item"]:not(:disabled, [aria-disabled="true"], [data-disabled]):active {
  --accent: var(--studio-main-control-pressed);
}

@media (any-pointer: coarse) {
  [data-preview-panel-mode="inline"] > [role="separator"][aria-orientation="vertical"],
  [data-preview-panel-mode="inline"] > [role="separator"][aria-orientation="vertical"] > [aria-hidden="true"] {
    left: 0;
  }
}

@media (forced-colors: none) {
  html[data-theme-id] {
    --studio-scrollbar-thumb: #b0b0b0;
    --studio-scrollbar-hover: #747474;
    --studio-scrollbar-active: #5a5a5a;
    --app-scrollbar-thumb: var(--studio-scrollbar-thumb);
    --app-scrollbar-thumb-hover: var(--studio-scrollbar-hover);
  }

  html.dark[data-theme-id] {
    --studio-scrollbar-thumb: #636363;
    --studio-scrollbar-hover: #909090;
    --studio-scrollbar-active: #adadad;
  }

  html[data-theme-id] :where(:not(iframe))::-webkit-scrollbar-thumb {
    background-color: var(--studio-scrollbar-thumb);
  }

  html[data-theme-id] :where(:not(iframe))::-webkit-scrollbar-thumb:hover {
    background-color: var(--studio-scrollbar-hover);
  }

  html[data-theme-id] :where(:not(iframe))::-webkit-scrollbar-thumb:active {
    background-color: var(--studio-scrollbar-active);
  }

  html[data-theme-id] [data-slot="scroll-area-thumb"] {
    --app-scrollbar-thumb: var(--studio-scrollbar-thumb);
    --app-scrollbar-thumb-hover: var(--studio-scrollbar-hover);
  }

  html[data-theme-id] :is(
    [data-slot="scroll-area-scrollbar"]:active > [data-slot="scroll-area-thumb"],
    [data-slot="scroll-area-thumb"]:active,
    [role="scrollbar"][aria-label="Terminal scrollback"]:active > div
  ) {
    background-color: var(--studio-scrollbar-active);
  }

  @supports selector(::-webkit-scrollbar-thumb) {
    html[data-theme-id] :is(.chat-markdown pre, [class~="[scrollbar-width:thin]"]) {
      scrollbar-width: auto;
      scrollbar-color: auto;
    }
  }
}

[data-scroll-to-end="true"]:not(:has(> span)) {
  inline-size: 2.25rem;
  block-size: 2.25rem;
  padding: 0;
  gap: 0;
  font-size: 0;
  line-height: 0;
  border-color: var(--app-theme-border, var(--border));
  border-radius: 50%;
  --studio-scroll-button-fill: var(--app-theme-surface-overlay, var(--popover));
  background-color: color-mix(in srgb, var(--studio-scroll-button-fill) var(--glass-opacity), transparent);
  color: var(--studio-composer-icon);
  box-shadow: var(--studio-composer-shadow);
  scale: none;
  transition: none;

  & > svg {
    color: inherit;
    inline-size: 1.125rem;
    block-size: 1.125rem;
    margin: 0;
  }

  & > svg > path {
    d: path("M12 4.5v15m-6-6 6 6 6-6");
    stroke-width: 1.8;
  }

  @media (hover: hover) {
    &:hover {
      --studio-scroll-button-fill: var(--studio-main-control-hover);
    }
  }

  &:active {
    --studio-scroll-button-fill: var(--studio-main-control-pressed);
  }

  &:focus-visible {
    outline: 2px solid var(--studio-composer-focus);
    outline-offset: 2px;
  }

  @media (prefers-reduced-motion: no-preference) {
    transition: background-color 110ms ease-out;
  }
}

[data-message-role="user"] div:has(> button:is([aria-label="Edit from here"], [aria-label="Copy message"], [aria-label="Copy prompt link"])),
:is([data-message-role="assistant"], [data-timeline-row-kind="assistant-meta"]) div:has(> button:is([aria-label="Copy message"], [aria-label="Fork from this response"], [aria-label="Reply to this response"])) {
  column-gap: 0.125rem;
}

[data-message-role="user"] div:has(> button:is([aria-label="Edit from here"], [aria-label="Copy message"], [aria-label="Copy prompt link"])) > button:is([aria-label="Edit from here"], [aria-label="Copy message"], [aria-label="Copy prompt link"]),
:is([data-message-role="assistant"], [data-timeline-row-kind="assistant-meta"]) div:has(> button:is([aria-label="Copy message"], [aria-label="Fork from this response"], [aria-label="Reply to this response"])) > button:is([aria-label="Copy message"], [aria-label="Fork from this response"], [aria-label="Reply to this response"]) {
  inline-size: 1.75rem;
  block-size: 1.75rem;
  padding-inline: 0;

  & > svg {
    inline-size: 0.875rem;
    block-size: 0.875rem;
    margin-inline: 0;
  }

  @media (pointer: fine) {
    inline-size: 1.5rem;
    block-size: 1.5rem;
  }
}

:is([data-message-role="assistant"], [data-timeline-row-kind="assistant-meta"]) div:has(> button:is([aria-label="Copy message"], [aria-label="Fork from this response"], [aria-label="Reply to this response"])) > p {
  margin-inline-start: 0.375rem;
}

:is([data-message-role="assistant"], [data-timeline-row-kind="assistant-meta"]) div:has(> button:is([aria-label="Copy message"], [aria-label="Fork from this response"], [aria-label="Reply to this response"])) > p,
[data-message-role="user"] div:has(> div > button:is([aria-label="Edit from here"], [aria-label="Copy message"], [aria-label="Copy prompt link"])) > p {
  color: #727272;
  white-space: nowrap;
}

html.dark :is(
  :is([data-message-role="assistant"], [data-timeline-row-kind="assistant-meta"]) div:has(> button:is([aria-label="Copy message"], [aria-label="Fork from this response"], [aria-label="Reply to this response"])) > p,
  [data-message-role="user"] div:has(> div > button:is([aria-label="Edit from here"], [aria-label="Copy message"], [aria-label="Copy prompt link"])) > p
) {
  color: #a6a6a6;
}

html[data-theme-id] {
  --studio-tooltip-surface: #1d1d1d;
  --studio-tooltip-text: #f8f8f8;
  --studio-tooltip-border: #333333;
  --studio-popup-border: #cfcfcf;
  --studio-popup-shadow: 0 8px 24px rgb(0 0 0 / 15%);
  --studio-menu-hover: #ebebeb;
  --studio-menu-selected: #dedede;
  --studio-menu-selected-hover: #d8d8d8;
  --studio-menu-pressed: #c9c9c9;
  --studio-record-surface: #fdfdfd;
  --studio-record-header: #eaeaea;
  --studio-record-rule: #d2d2d2;
  --studio-work-open: #e8e8e8;
  --studio-work-marker: #818181;
}

html.dark[data-theme-id] {
  --studio-tooltip-surface: #393939;
  --studio-tooltip-text: #f4f4f4;
